const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];

const EXPORT_W = 1536;
const EXPORT_H = 1024;
let race = "elyos";
let exportCache = { key: "", blob: null, file: null };
let exportPromise = null;
let exportTimer = null;
let exportVersion = 0;

const cardImage = $("#cardImage");
const cardImageSources = {
  elyos: "elyos.png",
  asmodian: "asmodian.png"
};

const inputs = {
  name: $("#name"),
  server: $("#server"),
  legion: $("#legion"),
  job: $("#job")
};

function setMark(key, active) {
  const el = $(`.${key}`);
  if (el) el.classList.toggle("is-on", active);
}

function updateProfile() {
  $(".overlay.name").textContent = inputs.name.value || "";
  $(".overlay.server").textContent = inputs.server.value || "";
  $(".overlay.legion").textContent = inputs.legion.value || "";
  $(".overlay.job").textContent = inputs.job.value || "";
}

function updatePlayStyle() {
  $$('[data-overlay]').forEach(input => setMark(input.dataset.overlay, input.checked));
}

function updateVC() {
  const selected = $("input[name=vc]:checked");
  const selectedIndex = selected ? Number(selected.dataset.vcIndex) : 0;
  $$(".vc-mark").forEach((el, i) => el.classList.toggle("is-on", i === selectedIndex));
}

function getStateKey() {
  const checks = $$('input[type=checkbox]').map(x => x.checked ? "1" : "0").join("");
  const vc = $("input[name=vc]:checked")?.dataset.vcIndex || "0";
  return [race, inputs.name.value, inputs.server.value, inputs.legion.value, inputs.job.value, checks, vc].join("\u001f");
}

function invalidateExport() {
  exportVersion++;
  exportCache = { key: "", blob: null, file: null };
}

function update() {
  updateProfile();
  updatePlayStyle();
  updateVC();
  invalidateExport();
  queueExport();
}

function setRace(next) {
  race = next;
  const img = $("#cardImage");
  img.src = cardImageSources[next];
  $(".friend-card").classList.toggle("asmo-card", next === "asmodian");
  $$(".race-btn").forEach(btn => btn.classList.toggle("active", btn.dataset.race === next));
  invalidateExport();
  queueExport();
}

Object.values(inputs).forEach(el => el.addEventListener("input", update));
$$('input[type=checkbox], input[type=radio]').forEach(el => el.addEventListener("change", update));
$$('.race-btn').forEach(btn => btn.addEventListener("click", () => setRace(btn.dataset.race)));

function getCardState() {
  const isAsmo = race === "asmodian";

  const profile = [
    { text: inputs.name.value, x: isAsmo ? 25.65 : 25.9, y: 31.6, size: 23.808 },
    { text: inputs.server.value, x: 25.9, y: 40.6, size: 17.664 },
    { text: inputs.legion.value, x: 25.9, y: 45.4, size: 17.664 },
    { text: inputs.job.value, x: 25.9, y: 50.1, size: 17.664 }
  ];

  const playNames = [
    "play-story", "play-pve", "play-pvp", "play-gather", "play-money",
    "play-growth", "play-ss", "play-chat", "play-relax", "play-hard"
  ];
  const playTop = isAsmo
    ? [65.33, 70.12, 74.80, 79.60, 84.28]
    : [63.77, 68.36, 72.85, 77.44, 82.03];
  const playLeft = isAsmo
    ? [13.48,13.48,13.48,13.48,13.48,30.86,30.86,30.86,30.86,30.86]
    : [14.2,14.2,14.2,14.2,14.2,31.12,31.12,31.12,31.12,31.12];
  const play = playNames.map((name, i) => ({
    active: $(`.${name}`).classList.contains("is-on"),
    x: playLeft[i], y: playTop[i % 5], size: 25.344
  }));

  const vcLeft = isAsmo ? [62.76,69.73,76.69,83.66] : [62.15,69.1,76.0,82.7];
  const vcY = isAsmo ? 36.91 : 36.2;
  const vc = vcLeft.map((x, i) => ({
    active: $(`.vc-${i}`).classList.contains("is-on"), x, y: vcY
  }));

  const weekdayLeft = isAsmo ? [56.38,63.41,70.25,77.02,83.92] : [56.25,63.15,69.73,76.56,83.40];
  const weekdayY = isAsmo ? 62.79 : 61.33;
  const holidayY = isAsmo ? 81.54 : 79.30;
  const weekdayNames = ["weekday-morning","weekday-noon","weekday-evening","weekday-night","weekday-late"];
  const holidayNames = ["holiday-morning","holiday-noon","holiday-evening","holiday-night","holiday-late"];
  const weekday = weekdayNames.map((n,i)=>({ active:$(`.${n}`).classList.contains("is-on"), x:weekdayLeft[i], y:weekdayY, size:22.272 }));
  const holiday = holidayNames.map((n,i)=>({ active:$(`.${n}`).classList.contains("is-on"), x:weekdayLeft[i], y:holidayY, size:22.272 }));

  return { profile, play, vc, weekday, holiday };
}

function waitForImage(img) {
  if (img.complete && img.naturalWidth > 0) return Promise.resolve();
  return new Promise((resolve, reject) => {
    const onLoad = () => { cleanup(); resolve(); };
    const onError = () => { cleanup(); reject(new Error(`画像の読み込みに失敗しました: ${img.src}`)); };
    const cleanup = () => {
      img.removeEventListener("load", onLoad);
      img.removeEventListener("error", onError);
    };
    img.addEventListener("load", onLoad, { once: true });
    img.addEventListener("error", onError, { once: true });
  });
}

// Canvasへ描画する画像は、同一オリジンからBlobとして読み直す。
// これにより、通常の<img>表示はそのまま維持しつつ、Canvasの
// 「Tainted canvases may not be exported」問題を回避する。

// Local-file fallback: when the site is opened directly from a ZIP/extracted folder
// (file://), fetch() is blocked by the browser. These data URIs are generated from
// the bundled PNG files so PNG export still works without requiring a web server.
const bundledCanvasData = {
  elyos: "data:image/png;base64,",
  asmodian: "data:image/png;base64,"
};

const canvasImageCache = new Map();
async function loadCanvasImage(src) {
  if (canvasImageCache.has(src)) return canvasImageCache.get(src);

  let objectUrl = null;
  try {
    // On normal HTTP/HTTPS hosting, use the actual PNG file from the ZIP.
    // On file:// hosting, fetch() is blocked, so fall back to data generated
    // directly from the bundled PNG bytes.
    if (location.protocol === "file:") {
      const key = src === cardImageSources.asmodian ? "asmodian" : "elyos";
      src = bundledCanvasData[key];
    } else {
      const response = await fetch(src, { cache: "no-store" });
      if (!response.ok) throw new Error(`カード画像の取得に失敗しました: ${src}`);
      const blob = await response.blob();
      objectUrl = URL.createObjectURL(blob);
      src = objectUrl;
    }

    const img = new Image();
    img.decoding = "async";
    img.src = src;
    await img.decode();
    canvasImageCache.set(src, img);
    return img;
  } catch (error) {
    if (objectUrl) URL.revokeObjectURL(objectUrl);
    throw error;
  }
}

function drawText(ctx, text, x, y, size, opts = {}) {
  if (!text) return;
  ctx.save();
  ctx.font = `${opts.weight || 700} ${size}px "Yu Gothic", "Hiragino Kaku Gothic ProN", system-ui, sans-serif`;
  ctx.textAlign = opts.align || "left";
  ctx.textBaseline = opts.baseline || "alphabetic";
  ctx.fillStyle = opts.fill || "#2f2730";
  ctx.shadowColor = opts.shadowColor || "rgba(255,255,255,.78)";
  ctx.shadowBlur = opts.shadowBlur ?? 4;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 1;
  if (opts.strokeWidth) {
    ctx.lineWidth = opts.strokeWidth;
    ctx.strokeStyle = opts.stroke || ctx.fillStyle;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    ctx.strokeText(text, x, y);
  }
  ctx.fillText(text, x, y);
  ctx.restore();
}

async function buildPngBlob() {
  if (document.fonts?.ready) await document.fonts.ready;
  const img = $("#cardImage");
  await waitForImage(img);
  const imageSrc = cardImageSources[race];
  if (!imageSrc) throw new Error("カード画像を安全に読み込めませんでした");
  const canvasImg = await loadCanvasImage(imageSrc);

  const { profile, play, vc, weekday, holiday } = getCardState();
  const canvas = document.createElement("canvas");
  canvas.width = EXPORT_W;
  canvas.height = EXPORT_H;
  const ctx = canvas.getContext("2d", { alpha: false });
  if (!ctx) throw new Error("Canvasが利用できません");
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = "high";
  ctx.drawImage(canvasImg, 0, 0, EXPORT_W, EXPORT_H);

  for (const p of profile) {
    drawText(ctx, p.text, p.x / 100 * EXPORT_W, p.y / 100 * EXPORT_H + p.size, p.size, {
      weight: 700,
      fill: race === "asmodian" ? "#5E1751" : "#365579"
    });
  }

  for (const p of play) {
    if (!p.active) continue;
    drawText(ctx, "✓", p.x / 100 * EXPORT_W, p.y / 100 * EXPORT_H, p.size, {
      weight: 900, align: "center", baseline: "middle",
      fill: race === "asmodian" ? "#6a3653" : "#405f88",
      strokeWidth: 1.2,
      stroke: race === "asmodian" ? "#6a3653" : "#405f88",
      shadowColor: "rgba(255,255,255,.8)", shadowBlur: 2
    });
  }

  // VC：プレビューと同じ「選択肢全体を囲むリング」を描画
  for (const p of vc) {
    if (!p.active) continue;
    const x = p.x / 100 * EXPORT_W;
    const y = p.y / 100 * EXPORT_H;
    const radius = 37.5;
    ctx.save();
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.strokeStyle = race === "asmodian" ? "#6c3658" : "#4d6f9c";
    ctx.lineWidth = 3;
    ctx.shadowColor = "rgba(255,255,255,.55)";
    ctx.shadowBlur = 2;
    ctx.stroke();
    ctx.restore();
  }

  for (const p of [...weekday, ...holiday]) {
    if (!p.active) continue;
    drawText(ctx, "✓", p.x / 100 * EXPORT_W, p.y / 100 * EXPORT_H + 1, p.size, {
      weight: 900, align: "center", baseline: "middle",
      fill: race === "asmodian" ? "#6a3653" : "#405f88",
      strokeWidth: 1.2,
      stroke: race === "asmodian" ? "#6a3653" : "#405f88",
      shadowColor: "rgba(255,255,255,.8)", shadowBlur: 2
    });
  }

  return await new Promise((resolve, reject) => {
    canvas.toBlob(result => {
      if (result) resolve(result);
      else reject(new Error("PNG変換に失敗しました（toBlobがnullを返しました）"));
    }, "image/png");
  });
}

function prepareExport() {
  const key = getStateKey();
  if (exportCache.key === key && exportCache.blob && exportCache.file) {
    return Promise.resolve(exportCache);
  }

  if (exportPromise) return exportPromise;

  const versionAtStart = exportVersion;
  exportPromise = buildPngBlob()
    .then(blob => {
      const currentKey = getStateKey();
      if (versionAtStart !== exportVersion || currentKey !== key) {
        return null;
      }
      const fileName = `AION2_FRIEND_CARD_${race === "elyos" ? "elyos" : "asmodian"}.png`;
      exportCache = { key, blob, file: new File([blob], fileName, { type: "image/png" }) };
      return exportCache;
    })
    .finally(() => {
      exportPromise = null;
    });

  return exportPromise;
}

function queueExport() {
  clearTimeout(exportTimer);
  exportTimer = setTimeout(() => {
    prepareExport().catch(error => console.error("PNG preparation error:", error));
  }, 180);
}

function downloadBlob(blob, fileName) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = fileName;
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 3000);
}

async function savePng() {
  const button = $("#savePngBtn");
  const original = button.textContent;
  const requestedKey = getStateKey();

  button.disabled = true;
  button.textContent = "⏳ PNGを作成中…";

  try {
    // PCでは共有APIを一切使わず、PNGを作成したら即ダウンロード。
    // Windows / macOS / Linux の一般的なデスクトップブラウザを対象にする。
    const isMobile = /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);

    invalidateExport();
    let result = await prepareExport();

    // 生成中に入力が変わった場合は、最新状態で作り直す。
    if (!result || result.key !== getStateKey()) {
      invalidateExport();
      result = await prepareExport();
    }

    if (!result?.blob) {
      throw new Error("PNGを作成できませんでした");
    }

    const fileName = `AION2_FRIEND_CARD_${race === "elyos" ? "elyos" : "asmodian"}.png`;

    if (!isMobile) {
      // PC：共有処理を完全にスキップして即ダウンロード。
      button.textContent = "⬇️ ダウンロード中…";
      downloadBlob(result.blob, fileName);
      return;
    }

    // スマホ：まず共有シートを試し、使えなければダウンロードへフォールバック。
    if (navigator.share && result.file && navigator.canShare?.({ files: [result.file] })) {
      try {
        await navigator.share({
          title: "AION2 FRIEND CARD",
          text: "AION2 FRIEND CARD",
          files: [result.file]
        });
        return;
      } catch (shareError) {
        if (shareError?.name === "AbortError") return;
        console.warn("共有に失敗したためダウンロードへ切り替えます:", shareError);
      }
    }

    downloadBlob(result.blob, fileName);
  } catch (error) {
    console.error("PNG save error:", error);
    alert(`PNGの保存に失敗しました。\n${error?.message || "原因を特定できませんでした。"}`);
  } finally {
    button.disabled = false;
    button.textContent = original;
  }
}

$("#savePngBtn").addEventListener("click", savePng);

setRace("elyos");
update();
